// 测试桩：只导出 plugin.js 真正 import 的三个名字。
// 少一个就会在 ESM 链接阶段抛 SyntaxError —— 这本身就是一道校验。

export const cn = (...parts) => parts.flat(Infinity).filter(Boolean).join(' ')

export const StatusDot = function StatusDot() {
  return null
}

// 真实 Tip（components/ui/tooltip.tsx:151-171）把 children 原样渲染进 TooltipTrigger，
// 桩必须同样转发，否则遍历渲染树时按钮子树不可见。
export const Tip = function Tip(props) {
  return props.children ?? null
}
